const existingJourneys = new Map(systemJourneys.map((journey) => [journey.id, journey]))

const simpleJourneys: LifeScenario[] = systemStories.map((story) => {
  const existing = existingJourneys.get(story.id)
  if (existing) {
    return {
      ...existing,
      title: story.title,
      situation: story.intro,
      goal: story.takeaway,
      storyScenes: story.scenes,
    }
  }
  return {
    id: story.id,
    title: story.title,
    icon: story.icon,
    roles: story.roles,
    person: story.person,
    situation: story.intro,
    goal: story.takeaway,
    systemJourney: {
      system: story.system,
      learningGoal: story.takeaway,
      timing: 'Use the linked scheduling lesson and current official calendar for the applicable run or processing window.',
    },
    storyScenes: story.scenes,
    startingConditions: 'Fictional learning scenario. The flight attendant must be eligible and remains responsible for existing duties until an authorized change is confirmed.',
    systems: [story.system],
    steps: story.scenes.map((scene) => ({
      time: scene.time, title: scene.title, action: scene.text,
      check: story.takeaway, systemState: scene.text,
    })),
    outcomes: [
      { label: 'Result confirmed', status: 'success', systemResult: story.takeaway, nextAction: 'Review the actual result and current schedule before relying on a change.', lifeImpact: 'Make personal arrangements around the confirmed work plan.' },
      { label: 'Still waiting', status: 'pending', systemResult: 'No final result has been confirmed.', nextAction: 'Check the applicable processing information; existing obligations remain.', lifeImpact: 'Keep backup personal arrangements.' },
      { label: 'Not as requested', status: 'warning', systemResult: 'The preference or transaction did not produce the desired change.', nextAction: 'Review the actual result and use official support for unclear information.', lifeImpact: 'Adjust personal plans rather than assuming a request was approved.' },
    ],
    roleDifference: story.roles.length === 1 && story.roles[0] === 'Reserve'
      ? 'This story is about reserve processes. Lineholder trip transactions do not replace reserve availability obligations.'
      : 'Use the process for the actual lineholder or reserve status and current eligibility; the two roles are not interchangeable.',
    verifyCurrent: 'Based on the academy scheduling lessons. Confirm current eligibility, processing windows, implementation and reporting instructions through official guidance.',
    lessonIds: [story.lessonId],
    relatedTerms: [story.termId],
    sources: [contract(story.system === 'TBS' ? 'Section 29: Training' : 'Sections 10 and 12: Scheduling and Reserve Duty'), monthly],
  }
})

export const lifeScenarios: LifeScenario[] = [...simpleJourneys, ...lifeSituations]
